"use client"

import { useEffect, useState, type ReactNode } from "react"

import {
  ResizableHandle,
  ResizablePanel,
  ResizablePanelGroup,
} from "@/components/ui/resizable"

export function CockpitShell({
  children,
  rightSidebar,
}: {
  children: ReactNode
  rightSidebar?: ReactNode
}) {
  return (
    <div className="flex h-dvh min-h-0 flex-col overflow-hidden">
      <WorkspacePanels rightSidebar={rightSidebar}>{children}</WorkspacePanels>
    </div>
  )
}

function WorkspacePanels({
  children,
  rightSidebar,
}: {
  children: ReactNode
  rightSidebar?: ReactNode
}) {
  const [showsCandidatePanel, setShowsCandidatePanel] = useState(false)

  useEffect(() => {
    const media = window.matchMedia("(min-width: 48rem)")
    const update = () => setShowsCandidatePanel(media.matches)

    update()
    media.addEventListener("change", update)
    return () => media.removeEventListener("change", update)
  }, [])

  if (!showsCandidatePanel) return children

  return (
    <ResizablePanelGroup orientation="horizontal" className="min-h-0 flex-1">
      <ResizablePanel id="conversation" minSize="30vw">
        {children}
      </ResizablePanel>
      {rightSidebar ? (
        <>
          <ResizableHandle withHandle />
          <ResizablePanel
            id="candidates"
            defaultSize="30vw"
            minSize="20vw"
            maxSize="50vw"
          >
            {rightSidebar}
          </ResizablePanel>
        </>
      ) : null}
    </ResizablePanelGroup>
  )
}
"use client"

import { Suspense, useEffect, useState } from "react"
import { useRouter, useSearchParams } from "next/navigation"

import {
  Conversation,
  ConversationContent,
  ConversationScrollButton,
} from "@/components/ai-elements/conversation"
import { CockpitShell } from "@/components/cockpit/cockpit-shell"
import { IncidentHeader } from "@/components/cockpit/incident-header"
import { LiveCandidatePanel } from "@/components/cockpit/live-candidate-panel"
import { PlanChecklist } from "@/components/cockpit/plan-checklist"
import { useDevinCase } from "@/hooks/use-devin-case"

export function CockpitChat() {
  return (
    <Suspense fallback={null}>
      <DevinCockpit />
    </Suspense>
  )
}

function DevinCockpit() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const caseFromUrl = searchParams.get("case")
  const devin = useDevinCase(caseFromUrl)
  const { status, launch } = devin
  const [candidatesOpen, setCandidatesOpen] = useState(true)

  useEffect(() => {
    if (caseFromUrl || status !== "idle") return
    void launch().then((caseId) => {
      if (caseId) router.replace(`/chat?case=${encodeURIComponent(caseId)}`)
    })
  }, [caseFromUrl, launch, router, status])

  async function startNewSession() {
    const caseId = await devin.launch()
    if (caseId) router.replace(`/chat?case=${encodeURIComponent(caseId)}`)
  }

  const incident = devin.snapshot?.incident ?? null
  const part = devin.snapshot?.part ?? null

  return (
    <CockpitShell
      rightSidebar={
        candidatesOpen ? (
          <LiveCandidatePanel
            candidates={devin.candidates}
            supplierRecords={devin.snapshot?.supplier_records ?? []}
            onClose={() => setCandidatesOpen(false)}
          />
        ) : undefined
      }
    >
      <div className="grid h-full min-h-0 min-w-0 grid-rows-[auto_minmax(0,1fr)] overflow-hidden">
        <IncidentHeader
          caseId={devin.caseId}
          incident={incident}
          part={part}
          sessionUrl={devin.session?.session_url ?? null}
          stubbed={devin.status === "stubbed"}
          running={devin.status === "launching"}
          onReplay={() => void startNewSession()}
          showOpenCandidates={!candidatesOpen}
          onOpenCandidates={() => setCandidatesOpen(true)}
        />
        <Conversation className="min-h-0">
          <ConversationContent
            className="mx-auto w-full max-w-[50vw] gap-4 px-4 py-4"
            scrollClassName="chat-scrollbar overflow-x-hidden overflow-y-auto"
          >
            <SessionBanner
              status={devin.status}
              error={devin.error}
              sessionUrl={devin.session?.session_url ?? null}
            />
            <PlanChecklist
              plan={devin.checklist}
              launching={devin.status === "launching"}
            />
          </ConversationContent>
          <ConversationScrollButton />
        </Conversation>
      </div>
    </CockpitShell>
  )
}

function SessionBanner({
  status,
  error,
  sessionUrl,
}: {
  status: string
  error: string | null
  sessionUrl: string | null
}) {
  if (status === "idle" || status === "launching") return null
  if (status === "error") {
    return (
      <p className="text-sm text-destructive" role="alert">
        {error ?? "The API did not start a Devin session."}
      </p>
    )
  }
  if (status === "stubbed") {
    return (
      <p className="text-sm text-amber-600">
        Case is open, but Devin was stubbed. Set{" "}
        <code>DEVIN_API_KEY</code> on the API and start a new session.
        {error ? ` ${error}` : ""}
      </p>
    )
  }
  return (
    <p className="text-sm text-muted-foreground">
      Devin session is live
      {sessionUrl ? (
        <>
          {" · "}
          <a
            href={sessionUrl}
            target="_blank"
            rel="noreferrer"
            className="underline underline-offset-4"
          >
            open session
          </a>
        </>
      ) : null}
    </p>
  )
}

import {
  CheckIcon,
  CircleIcon,
  Loader2Icon,
  Phone,
  XIcon,
} from "@/components/icons"
import { DotLoader } from "@/components/cockpit/dot-loader"
import type { LivePlan, LivePlanStep, LiveStepStatus } from "@/lib/live/plan"
import { cn } from "@/lib/utils"

export function PlanChecklist({
  plan,
  launching,
}: {
  plan: LivePlan | null
  launching: boolean
}) {
  if (launching && !plan) {
    return (
      <div className="flex items-center gap-2 text-sm text-muted-foreground">
        <DotLoader className="size-4" />
        <span>Opening the case…</span>
      </div>
    )
  }

  if (!plan) {
    return (
      <p className="text-sm text-muted-foreground">
        No checklist yet. It appears when the case opens.
      </p>
    )
  }

  const percent = plan.total ? Math.round((plan.done / plan.total) * 100) : 0
  const liveCalls = plan.sections
    .flatMap((section) => section.steps)
    .filter(
      (step) =>
        step.group === "outreach" &&
        step.supplier_ref &&
        step.status === "active"
    )

  return (
    <div className="flex flex-col gap-8">
      <header className="flex flex-col gap-3">
        <div className="flex items-baseline justify-between gap-3">
          <h2 className="text-sm font-medium">What the agent is doing</h2>
          <p className="font-mono text-xs text-muted-foreground tabular-nums">
            {plan.done}/{plan.total}
          </p>
        </div>
        <div className="h-px overflow-hidden bg-border/70">
          <div
            className="h-full bg-foreground/80 transition-[width] duration-500 ease-out"
            style={{ width: `${percent}%` }}
          />
        </div>
      </header>

      <ol className="flex flex-col gap-7">
        {plan.sections.map((section) => {
          const status = section.status ?? "pending"
          return (
          <li key={section.group} className="flex flex-col gap-2.5">
            <div className="flex items-center gap-2">
              <span
                aria-hidden="true"
                className={cn(
                  "size-1.5 rounded-full",
                  status === "done" && "bg-foreground",
                  status === "active" && "bg-foreground/70",
                  status === "failed" && "bg-destructive",
                  (status === "pending" || status === "skipped") &&
                    "bg-muted-foreground/30"
                )}
              />
              <h3
                className={cn(
                  "text-[13px] font-medium",
                  status === "pending"
                    ? "text-muted-foreground"
                    : "text-foreground"
                )}
              >
                {section.label}
              </h3>
            </div>
            <ul className="ml-2 flex flex-col border-l border-border/70 pl-4">
              {section.steps.length === 0 ? (
                <li className="py-1.5 text-[13px] text-muted-foreground">
                  {section.group === "outreach"
                    ? "Waiting for Devin to name who to call."
                    : "Not started."}
                </li>
              ) : (
                section.steps.map((step) => (
                  <StepRow key={step.step_id} step={step} />
                ))
              )}
            </ul>
            {section.group === "outreach" && liveCalls.length > 1 ? (
              <p className="ml-6 text-[11px] text-muted-foreground">
                {liveCalls.length} shown in parallel. One live dial to the demo
                number.
              </p>
            ) : null}
          </li>
          )
        })}
      </ol>
    </div>
  )
}

function StepRow({ step }: { step: LivePlanStep }) {
  const calling = Boolean(step.supplier_ref && step.group === "outreach")
  const Icon = iconFor(step.status, calling)

  return (
    <li className="flex items-start gap-2.5 py-1.5">
      <Icon
        aria-hidden="true"
        className={cn(
          "mt-0.5 size-3.5 shrink-0",
          toneFor(step.status),
          step.status === "active" && !calling && "animate-spin"
        )}
      />
      <div className="min-w-0">
        <p
          className={cn(
            "text-sm leading-5",
            step.status === "pending" && "text-muted-foreground",
            step.status === "active" && "text-foreground",
            step.status === "done" && "text-foreground/80",
            step.status === "failed" && "text-destructive",
            step.status === "skipped" && "text-muted-foreground line-through"
          )}
        >
          {step.label}
        </p>
        {step.detail ? (
          <p className="mt-0.5 text-xs leading-5 text-muted-foreground">
            {step.detail}
          </p>
        ) : step.status === "active" && calling ? (
          <p className="mt-0.5 text-xs leading-5 text-muted-foreground">
            Dialing…
          </p>
        ) : null}
      </div>
    </li>
  )
}

function iconFor(status: LiveStepStatus, calling: boolean) {
  if (status === "active" && calling) return Phone
  if (status === "active") return Loader2Icon
  if (status === "done") return CheckIcon
  if (status === "failed") return XIcon
  return CircleIcon
}

function toneFor(status: LiveStepStatus): string {
  if (status === "active") return "text-foreground"
  if (status === "done") return "text-foreground/70"
  if (status === "failed") return "text-destructive"
  return "text-muted-foreground/50"
}
"use client"

import { useRouter } from "next/navigation"

import { Bot } from "@/components/icons"
import { DotLoader } from "@/components/cockpit/dot-loader"
import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { CALLS, type CallingAgentRun } from "@/lib/case-001"

export function AgentCallActivity({
  agentRuns,
}: {
  agentRuns: readonly CallingAgentRun[]
}) {
  const router = useRouter()
  const visibleRuns = [...agentRuns]
    .filter((agent) => agent.phase !== "queued")
    .sort((left, right) => (left.startedAt ?? 0) - (right.startedAt ?? 0))

  function openCall(callId: string) {
    const nextParams = new URLSearchParams(window.location.search)
    nextParams.set("call", callId)
    router.replace(`${window.location.pathname}?${nextParams.toString()}`, {
      scroll: false,
    })
  }

  if (visibleRuns.length === 0) return null

  return (
    <div className="grid gap-1" aria-label="Calling agents">
      {visibleRuns.map((agent) => {
        const call = CALLS.find((item) => item.id === agent.callId)
        if (!call) return null
        const complete = agent.phase === "complete"

        return (
          <button
            key={agent.callId}
            type="button"
            className="agent-inline-call group flex w-full items-start gap-2 rounded-lg px-2 py-1.5 text-left outline-none hover:bg-muted/60 focus-visible:ring-2 focus-visible:ring-ring"
            data-complete={complete}
            onClick={() => openCall(agent.callId)}
            aria-label={`Open ${complete ? "completed" : "active"} call with ${call.supplier}`}
          >
            <Avatar size="sm" className="mt-0.5 after:border-0">
              <AvatarFallback className={agent.avatarClassName}>
