export type PromptInputSubmitProps = ComponentProps<typeof InputGroupButton> & {
  status?: ChatStatus
  onStop?: () => void
}

export function PromptInputSubmit({
  status,
  onStop,
  children,
  onClick,
  ...props
}: PromptInputSubmitProps) {
  const canStop = status === "streaming" && Boolean(onStop)
  const icon =
    status === "submitted" ? (
      <Spinner />
    ) : status === "streaming" ? (
      <SquareIcon />
    ) : status === "error" ? (
      <XIcon />
    ) : (
      <CornerDownLeftIcon />
    )

  return (
    <InputGroupButton
      aria-label={
        status === "submitted"
          ? "Sending message"
          : status === "streaming"
            ? "Stop generating"
            : "Submit message"
      }
      size="icon-sm"
      type={canStop ? "button" : "submit"}
      variant="default"
      className="bg-foreground text-background hover:bg-foreground/80"
      onClick={(event) => {
        if (canStop && onStop) {
          event.preventDefault()
          onStop()
        } else {
          onClick?.(event)
        }
      }}
      {...props}
    >
      {children ?? icon}
    </InputGroupButton>
  )
}
