          record={recordsById.get(selected.supplier_ref)}
          onClose={() => setSelectedRef(null)}
        />
      ) : null}
    </aside>
  )
}

function PolicyPill({ passed }: { passed: boolean }) {
  return (
    <span
      className={cn(
