      >
        {props.running ? (
          <DotLoader />
        ) : (
          <RotateCcwIcon data-icon="inline-start" />
        )}
        {props.running ? "Running" : "New session"}
      </Button>
      {props.sessionUrl ? (
        <a
          href={props.sessionUrl}
          target="_blank"
          rel="noreferrer"
          className="px-2 text-xs text-muted-foreground underline-offset-4 hover:underline"
